using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
if(args.Length!=1)throw new ArgumentException("Usage: Showcase.Assets <frontend/dist>");
var dist=Path.GetFullPath(args[0]);var root=Path.GetFullPath(Path.Combine(dist,"../.."));
var all=new List<Asset>();var header=new StringBuilder("// Generated by Showcase.Assets. Same Vue build, simulator chunks excluded.\n#pragma once\n#include <cstddef>\n#include <cstdint>\nnamespace showcase_assets {\n");
foreach(var file in Directory.GetFiles(dist,"*",SearchOption.AllDirectories).Where(p=>!p.EndsWith(".gz")&&!p.EndsWith("manifest.json")).Order()){
 var bytes=File.ReadAllBytes(file);using var output=new MemoryStream();using(var gz=new GZipStream(output,CompressionLevel.SmallestSize,true))gz.Write(bytes);var compressed=output.ToArray();File.WriteAllBytes(file+".gz",compressed);
 var name=Path.GetRelativePath(dist,file).Replace('\\','/');bool simulator=name.Contains("SimulatorPanel-",StringComparison.Ordinal);
 var mime=Path.GetExtension(file) switch{".html"=>"text/html; charset=utf-8",".js"=>"application/javascript; charset=utf-8",".css"=>"text/css; charset=utf-8",".woff"=>"font/woff",".txt"=>"text/plain; charset=utf-8",_=>"application/octet-stream"};
 var asset=new Asset(name,bytes.Length,compressed.Length,Convert.ToHexStringLower(SHA256.HashData(bytes)),Convert.ToHexStringLower(SHA256.HashData(compressed)),simulator,mime);all.Add(asset);
 if(!simulator){header.Append($"inline const uint8_t file_{all.Count}[] = {{\n");for(int i=0;i<compressed.Length;i++){header.Append($"0x{compressed[i]:x2},");if(i%24==23)header.AppendLine();}header.AppendLine("\n};");}
 Console.WriteLine($"{name}: {compressed.Length} B gzip ({(simulator?"local simulator only":"device + simulator")})");
}
header.AppendLine("struct Asset { const char *path; const char *mime; const uint8_t *data; size_t length; };\ninline const Asset files[] = {");for(int i=0;i<all.Count;i++)if(!all[i].simulator_only){var a=all[i];header.AppendLine($"{{\"{(a.path=="index.html"?"/":"/"+a.path)}\",\"{a.mime}\",file_{i+1},sizeof(file_{i+1})}},");}header.AppendLine("};\n}");
File.WriteAllText(Path.Combine(root,"main/assets.hpp"),header.ToString());
var device=all.Where(a=>!a.simulator_only).ToArray();var json=new JsonSerializerOptions{WriteIndented=true};
File.WriteAllText(Path.Combine(dist,"asset-manifest.json"),JsonSerializer.Serialize(new{gzip_total_bytes=all.Sum(a=>a.gzip_bytes),device_gzip_bytes=device.Sum(a=>a.gzip_bytes),simulator_only_gzip_bytes=all.Where(a=>a.simulator_only).Sum(a=>a.gzip_bytes),files=all},json));
File.WriteAllText(Path.Combine(dist,"device-manifest.json"),JsonSerializer.Serialize(new{gzip_total_bytes=device.Sum(a=>a.gzip_bytes),files=device},json));
if(all.Sum(a=>a.gzip_bytes)>160*1024)throw new Exception("UI exceeds compressed budget");Console.WriteLine($"TOTAL {all.Sum(a=>a.gzip_bytes)} B; DEVICE {device.Sum(a=>a.gzip_bytes)} B; SIMULATOR ONLY {all.Where(a=>a.simulator_only).Sum(a=>a.gzip_bytes)} B");
record Asset(string path,int bytes,int gzip_bytes,string sha256,string gzip_sha256,bool simulator_only,string mime);
